import type { Metadata } from "next";
import { SITE_NAME } from "./site";

// The share card generated by app/opengraph-image.tsx.
const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "SPARK: we build websites & digital solutions" };

/**
 * Title, description, canonical URL and social cards for an inner page. Next
 * merges metadata shallowly (a page's `openGraph` replaces the root's, share
 * image included), so everything is spelled out here.
 */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const fullTitle = `${title} | ${SITE_NAME}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title: fullTitle,
      description,
      images: [SHARE_IMAGE],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [SHARE_IMAGE] },
  };
}
